_css.custom:
body.pfz .pfz-home__foot-inner {
  padding-inline: 1.5rem !important;
}
@media (min-width: 1024px) {
  body.pfz .pfz-home__foot-inner {
    padding-inline: 2.5rem !important;
  }
}

/* Footer — Bricks: full-width band (nested container max-width + section padding squeeze) */
body.pfz #brx-content section.pfz-home__foot.brxe-section,
body.pfz #brx-content footer.pfz-home__foot {
  width: 100% !important;
  max-width: none !important;
  padding-inline: 0 !important;
  margin-inline: 0 !important;
}

body.pfz #brx-content section.pfz-home__foot > .brxe-container,
body.pfz #brx-content footer.pfz-home__foot > .brxe-container {
  width: 100% !important;
  max-width: none !important;
  padding-inline: 0 !important;
  margin-inline: 0 !important;
}

body.pfz #brx-content section.pfz-home__foot .brxe-code {
  width: 100%;
}

/* ═══════════════════════════════════════════════════════════════════
 * Homepage section layouts (Bricks-rendered v6 home page).
 *
 * The Next.js v6 preview gets layout from Tailwind utility classes and
 * React inline styles which don't ship to WordPress. These rules give
 * the Bricks home page identical layouts via plain CSS classes that
 * the generators in scripts/lib/bricks-home-content.mjs apply.
 *
 * Naming: pfz-home__<section>-<part> (BEM, kept under .pfz so it scopes
 * cleanly with the rest of v2.css and doesn't leak to wp-admin).
 * ═══════════════════════════════════════════════════════════════════ */

/* ── shared ── */

.pfz .pfz-home__shell {
  width: 100%;
  max-width: 1480px;
  margin-inline: auto;
  padding-inline: 1.5rem;
}
@media (min-width: 1024px) {
  .pfz .pfz-home__shell {
    padding-inline: 2.5rem;
  }
}

.pfz .pfz-home__sec {
  position: relative;
  isolation: isolate;
  background: var(--base);
  color: var(--contrast);
}

.pfz .pfz-home__sec--ink {
  background: var(--base-ultra-dark);
}

.pfz .pfz-home__sec--paper-light {
  background: var(--base-light);
}

/* Section vertical rhythm — matches v6 React (py-24 lg:py-32) */
.pfz .pfz-home__sec-pad {
  padding-block: 6rem;
}
@media (min-width: 1024px) {
  .pfz .pfz-home__sec-pad {
    padding-block: 8rem;
  }
}

/* Hairline rule across full width (replaces Tailwind border-t pattern) */
.pfz .pfz-rule {
  height: 1px;
  background: var(--border);
  margin-block: 0;
}
.pfz .pfz-rule--ink {
  background: var(--border-on-dark);
}

/* Section meta-row: eyebrow+H2 on left, supporting paragraph on right. */
.pfz .pfz-home__meta-row {
  margin-bottom: 4rem;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1.5rem;
}
.pfz .pfz-home__meta-row--gap-lg {
  margin-bottom: 5rem;
}
.pfz .pfz-home__meta-h2 {
  margin-top: 0.75rem;
  max-width: 48rem;
}
.pfz .pfz-home__meta-body {
  max-width: 28rem;
}

/* ── §1 Hero ── */

.pfz .pfz-home__hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--base);
  color: var(--contrast);
}

.pfz .pfz-home__hero-darken,
.pfz .pfz-home__hero-top-fade,
.pfz .pfz-home__hero-void,
.pfz .pfz-home__hero-bottom-fade {
  position: absolute;
  pointer-events: none;
  z-index: 1;
}
.pfz .pfz-home__hero-darken {
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
}
.pfz .pfz-home__hero-top-fade {
  inset-inline: 0;
  top: 0;
  height: 8rem;
  background: linear-gradient(180deg, rgba(5, 5, 7, 0.75) 0%, transparent 100%);
}
.pfz .pfz-home__hero-void {
  inset: 0;
  background: radial-gradient(
    ellipse 68% 72% at 32% 52%,
    rgba(5, 5, 7, 0.28) 0%,
    rgba(5, 5, 7, 0.1) 42%,
    transparent 72%
  );
}
.pfz .pfz-home__hero-bottom-fade {
  inset-inline: 0;
  bottom: 0;
  height: 10rem;
  background: linear-gradient(
    180deg,
    transparent 0%,
    var(--base) 70%,
    var(--base) 100%
  );
}

.pfz .pfz-home__hero-inner {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  min-height: 100svh;
  width: 100%;
  max-width: 1480px;
  margin-inline: auto;
  padding: 7rem 1.5rem 4rem;
}
@media (min-width: 1024px) {
  .pfz .pfz-home__hero-inner {
    padding: 8rem 2.5rem 6rem;
  }
}

.pfz .pfz-home__hero-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 3rem;
}

.pfz .pfz-home__hero-headline {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.pfz .pfz-home__hero-h1 {
  max-width: min(32ch, 100%);
}

.pfz .pfz-home__hero-lede {
  margin-top: 2rem;
  max-width: 42rem;
  color: var(--secondary);
}

.pfz .pfz-home__hero-cta {
  margin-top: 2.5rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
}

/* Eyebrow with availability dot (pfz-eyebrow--primary already handles color) */
.pfz .pfz-home__avail-dot {
  display: inline-block;
  width: 0.4em;
  height: 0.4em;
  border-radius: 50%;
  margin-right: 0.5em;
  background: var(--primary);
  box-shadow: 0 0 10px 1px var(--primary-glow);
  vertical-align: middle;
}

/* ── §2 Industries ── */

.pfz .pfz-home__ind-body {
  display: grid;
  gap: 2.5rem;
}
@media (min-width: 1024px) {
  .pfz .pfz-home__ind-body {
    grid-template-columns: 0.85fr 1.15fr;
    gap: 3.5rem;
  }
}

.pfz .pfz-home__ind-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
}
.pfz .pfz-home__ind-list > li,
.pfz .pfz-home__ind-list > .pfz-home__ind-slot {
  border-bottom: 1px solid var(--border);
}

.pfz .pfz-home__ind-row {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  padding-block: 1.5rem;
  text-align: left;
  background: transparent;
  border: 0;
  color: var(--contrast-muted);
  font-family: var(--text-sans);
}
.pfz .pfz-home__ind-row:hover,
.pfz .pfz-home__ind-row:focus,
.pfz .pfz-home__ind-row.is-active {
  color: var(--contrast);
}
.pfz .pfz-home__ind-row-num {
  font-family: var(--text-mono);
  font-size: 12px;
  letter-spacing: 0.16em;
  color: var(--contrast-muted-low);
  margin-right: 1.25rem;
}
.pfz .pfz-home__ind-row.is-active .pfz-home__ind-row-num {
  color: var(--primary);
}
.pfz .pfz-home__ind-row-label {
  font-size: clamp(1.5rem, 2.4vw, 2.25rem);
  font-weight: 500;
  letter-spacing: -0.025em;
  line-height: 1.05;
}
.pfz .pfz-home__ind-row-meta {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin-left: 1rem;
  font-family: var(--text-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--contrast-muted-low);
}
.pfz .pfz-home__ind-row.is-active .pfz-home__ind-row-meta {
  color: var(--primary);
}
.pfz .pfz-home__ind-row-meta::before {
  content: "";
  display: inline-block;
  height: 1px;
  width: 0.75rem;
  background: var(--contrast-muted-low);
}
.pfz .pfz-home__ind-row.is-active .pfz-home__ind-row-meta::before {
  width: 2rem;
  background: var(--primary);
}

@media (min-width: 1024px) {
  .pfz .pfz-home__ind-preview-col {
    position: sticky;
    top: 8rem;
    align-self: start;
  }
}

/* Industry preview card (procedural panel) */
.pfz .pfz-card {
  position: relative;
  border-radius: 18px;
  border: 1px solid var(--border-strong);
  background: var(--base-light);
  overflow: hidden;
}

.pfz .pfz-home__ind-preview-card > .pfz-home__ind-preview-shot {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.pfz .pfz-home__ind-preview-card > .pfz-home__ind-preview-shot img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.38;
}

.pfz .pfz-home__ind-preview {
  min-height: 480px;
  display: grid;
  gap: 2rem;
  padding: 2rem;
}
@media (min-width: 1024px) {
  .pfz .pfz-home__ind-preview {
    padding: 2.5rem;
  }
}
.pfz .pfz-home__ind-preview-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}
.pfz .pfz-home__ind-preview-inner {
  position: relative;
  display: grid;
  gap: 2rem;
  z-index: 2;
}
.pfz .pfz-home__ind-preview-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.pfz .pfz-home__ind-preview-kicker {
  font-family: var(--text-mono);
  font-size: 11px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--contrast-muted-mid);
}
.pfz .pfz-home__ind-preview-dot {
  display: inline-block;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
}
.pfz .pfz-home__ind-preview-h3 {
  font-size: clamp(1.75rem, 3.4vw, 3rem);
  font-weight: 500;
  letter-spacing: -0.03em;
  line-height: 0.98;
  color: var(--contrast);
  max-width: 14ch;
}
.pfz .pfz-home__ind-preview-deliv {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.625rem;
}
@media (min-width: 640px) {
  .pfz .pfz-home__ind-preview-deliv {
    grid-template-columns: 1fr 1fr;
  }
}
.pfz .pfz-home__ind-preview-deliv li {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-family: var(--text-sans);
  font-size: 14px;
  color: var(--secondary);
}
.pfz .pfz-home__ind-preview-deliv li::before {
  content: "";
  display: inline-block;
  height: 1px;
  width: 0.75rem;
  background: currentColor;
  opacity: 0.65;
}
.pfz .pfz-home__ind-preview-proof {
  border-top: 1px solid var(--border);
  padding-top: 1.25rem;
  font-family: var(--text-serif);
  font-style: italic;
  font-size: clamp(1rem, 1.4vw, 1.3rem);
  line-height: 1.35;
  color: var(--secondary);
}

/* ── §3 Founder / About ── */

.pfz .pfz-home__founder-grid {
  display: grid;
  gap: 3rem;
  align-items: center;
}
@media (min-width: 1024px) {
  .pfz .pfz-home__founder-grid {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
    gap: 4rem;
  }
}
.pfz .pfz-home__founder-portrait {
  position: relative;
  aspect-ratio: 3/4;
  width: 100%;
  max-width: 28rem;
  overflow: hidden;
  border-radius: 18px;
  border: 1px solid var(--border-strong);
  background: var(--base-light);
}
@media (min-width: 1024px) {
  .pfz .pfz-home__founder-portrait {
    max-width: none;
  }
}
.pfz .pfz-home__founder-copy {
  max-width: 36rem;
}
.pfz .pfz-home__founder-lede {
  margin-top: 2rem;
}
.pfz .pfz-home__founder-body {
  margin-top: 1.25rem;
}
.pfz .pfz-home__founder-cta {
  margin-top: 2.5rem;
  display: inline-flex;
}

/* Bricks Image — founder portrait (sibling overlay HTML blocks use z-index above). */
.pfz .pfz-home__founder-portrait .pfz-home__founder-photo {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
}
.pfz .pfz-home__founder-portrait .pfz-home__founder-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ── §4 Branding (case wall + brand spreads) ── */

.pfz .pfz-home__brand-meta-row {
  margin-bottom: 5rem;
}

.pfz .pfz-home__brand-wall {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  background: var(--border-on-dark);
  margin-bottom: 6rem;
}
@media (min-width: 640px) {
  .pfz .pfz-home__brand-wall {
    grid-template-columns: repeat(4, 1fr);
  }
}
.pfz .pfz-home__brand-wall-cell {
  position: relative;
  aspect-ratio: 2/1;
  overflow: hidden;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.02),
    transparent
  );
}
.pfz .pfz-home__brand-wall-name {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: var(--text-sans);
  font-size: clamp(1.4rem, 2.4vw, 2.2rem);
  font-weight: 500;
  letter-spacing: -0.03em;
  color: var(--contrast);
}
.pfz .pfz-home__brand-wall-foot {
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1rem;
  background: linear-gradient(180deg, transparent, rgba(0, 0, 0, 0.4));
  font-family: var(--text-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.pfz .pfz-home__brand-wall-foot-ind {
  color: var(--contrast-muted);
}
.pfz .pfz-home__brand-wall-foot-yr {
  color: var(--primary);
}

.pfz .pfz-home__brand-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6rem;
}
@media (min-width: 1024px) {
  .pfz .pfz-home__brand-list {
    gap: 10rem;
  }
}

.pfz .pfz-home__brand-spread {
  display: grid;
  align-items: center;
  gap: 2.5rem;
}
@media (min-width: 1024px) {
  .pfz .pfz-home__brand-spread {
    grid-template-columns: repeat(12, 1fr);
    gap: 4rem;
  }
}
.pfz .pfz-home__brand-spread--flip {
  direction: rtl;
}
.pfz .pfz-home__brand-spread > * {
  direction: ltr;
}
@media (min-width: 1024px) {
  .pfz .pfz-home__brand-spread-mono {
    grid-column: span 7;
  }
  .pfz .pfz-home__brand-spread-detail {
    grid-column: span 5;
  }
}

.pfz .pfz-home__brand-mono {
  position: relative;
  aspect-ratio: 5/4;
  overflow: hidden;
  border-radius: 1rem;
  border: 1px solid var(--border-on-dark);
  background: var(--base-light);
}
.pfz .pfz-home__brand-mono-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.pfz .pfz-home__brand-mono-overlay {
  position: absolute;
  inset: 0;
  opacity: 0.3;
  mix-blend-mode: screen;
  pointer-events: none;
}
.pfz .pfz-home__brand-mono-bracket {
  position: absolute;
  width: 0.75rem;
  height: 0.75rem;
  border-color: var(--border-on-dark);
}
.pfz .pfz-home__brand-mono-bracket--tl {
  top: 1rem;
  left: 1rem;
  border-top: 1px solid;
  border-left: 1px solid;
}
.pfz .pfz-home__brand-mono-bracket--tr {
  top: 1rem;
  right: 1rem;
  border-top: 1px solid;
  border-right: 1px solid;
}
.pfz .pfz-home__brand-mono-bracket--bl {
  bottom: 1rem;
  left: 1rem;
  border-bottom: 1px solid;
  border-left: 1px solid;
}
.pfz .pfz-home__brand-mono-bracket--br {
  bottom: 1rem;
  right: 1rem;
  border-bottom: 1px solid;
  border-right: 1px solid;
}
.pfz .pfz-home__brand-mono-meta {
  position: absolute;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-family: var(--text-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--contrast-muted);
}
.pfz .pfz-home__brand-mono-meta--tl {
  top: 1.5rem;
  left: 1.5rem;
}
.pfz .pfz-home__brand-mono-meta--tr {
  top: 1.5rem;
  right: 1.5rem;
  text-align: right;
  color: var(--primary);
}
.pfz .pfz-home__brand-mono-glyph {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: var(--text-sans);
  font-weight: 500;
  font-size: clamp(7rem, 18vw, 16rem);
  letter-spacing: -0.06em;
  line-height: 0.85;
  color: var(--contrast);
}
.pfz .pfz-home__brand-mono-pal {
  position: absolute;
  bottom: 1.5rem;
  left: 1.5rem;
  display: flex;
  height: 6px;
  width: 8rem;
}
.pfz .pfz-home__brand-mono-pal > span {
  flex: 1;
}
.pfz .pfz-home__brand-mono-deliv {
  position: absolute;
  bottom: 1.5rem;
  right: 1.5rem;
  text-align: right;
  font-family: var(--text-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--contrast-muted);
}

/* Brand spread detail column */
.pfz .pfz-home__brand-spread-h3 {
  margin-top: 1rem;
  font-family: var(--text-sans);
  font-size: clamp(2rem, 3.6vw, 3.5rem);
  font-weight: 500;
  letter-spacing: -0.03em;
  line-height: 1;
  color: var(--contrast);
}
.pfz .pfz-home__brand-spread-h3 .pfz-display__accent {
  color: var(--primary);
}
.pfz .pfz-home__brand-spread-tag {
  margin-top: 1rem;
  max-width: 28rem;
  font-family: var(--text-serif);
  font-style: italic;
  font-size: clamp(1.1rem, 1.5vw, 1.4rem);
  line-height: 1.3;
  color: var(--secondary);
}
.pfz .pfz-home__brand-spread-dl {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem 1.5rem;
  margin-top: 1.5rem;
  font-family: var(--text-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--contrast-muted);
}
.pfz .pfz-home__brand-spread-dl dt {
  color: var(--contrast-muted-mid);
}
.pfz .pfz-home__brand-spread-dl dd {
  margin: 0.125rem 0 0;
  color: var(--contrast);
}
.pfz .pfz-home__brand-spread-summary {
  margin-top: 2rem;
  max-width: 28rem;
  font-family: var(--text-sans);
  font-size: 15px;
  line-height: 1.55;
  color: var(--contrast-muted);
}
.pfz .pfz-home__brand-spread-pal-label,
.pfz .pfz-home__brand-spread-type-label {
  margin: 2rem 0 0.75rem;
  font-family: var(--text-mono);
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--contrast-muted-mid);
}
.pfz .pfz-home__brand-spread-pal {
  display: flex;
  height: 3rem;
  max-width: 28rem;
  border-radius: 6px;
  overflow: hidden;
}
.pfz .pfz-home__brand-spread-pal > span {
  flex: 1;
}
.pfz .pfz-home__brand-spread-typepair {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.25rem 1rem;
}
.pfz .pfz-home__brand-spread-typepair-display {
  font-family: var(--text-sans);
  font-weight: 500;
  font-size: clamp(1.3rem, 1.9vw, 1.7rem);
  letter-spacing: -0.02em;
  color: var(--contrast);
  line-height: 1;
}
.pfz .pfz-home__brand-spread-typepair-italic {
  font-family: var(--text-serif);
  font-style: italic;
  font-size: clamp(1.6rem, 2.4vw, 2.1rem);
  color: var(--contrast);
  line-height: 1;
}
.pfz .pfz-home__brand-spread-typepair-body {
  font-family: var(--text-sans);
  font-size: 14px;
  color: var(--contrast-muted);
}
.pfz .pfz-home__brand-spread-deliv {
  list-style: none;
  margin: 2rem 0 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.pfz .pfz-home__brand-spread-deliv li {
  border: 1px solid var(--border-on-dark);
  border-radius: 999px;
  padding: 0.375rem 0.875rem;
  font-family: var(--text-mono);
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--contrast-muted);
}
.pfz .pfz-home__brand-spread-cta {
  margin-top: 2.5rem;
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  font-family: var(--text-sans);
