  border-top: none !important;
}

body.pfz #brx-content section#websites ol.pfz-home__web-slot-list,
body.pfz #brx-content section#websites div.pfz-home__web-slot-list {
  list-style: none !important;
  margin: 0 !important;
  padding: 0 !important;
  display: flex !important;
  flex-direction: column !important;
}

body.pfz #brx-content section#websites li.pfz-home__web-slot,
body.pfz #brx-content section#websites div.pfz-home__web-slot {
  display: flex !important;
  flex-direction: column !important;
  justify-content: flex-start !important;
  box-sizing: border-box !important;
  min-height: 0 !important;
  height: auto !important;
  padding-block: 2rem !important;
  border-top: 1px solid var(--border);
}

@media (min-width: 1024px) {
  body.pfz #brx-content section#websites li.pfz-home__web-slot,
  body.pfz #brx-content section#websites div.pfz-home__web-slot {
    padding-block: 2rem 2.75rem !important;
  }
}

body.pfz #brx-content section#websites li.pfz-home__web-slot:first-child,
body.pfz #brx-content section#websites div.pfz-home__web-slot:first-child {
  border-top: none !important;
}

.pfz .pfz-home__web-slot-main {
